/**
 * Coordinates returned by charCoords.
 *
 * @public
 * @unofficial
 */
export interface Cm5EditorCharCoords {
  /** The bottom coordinate in pixels. */
  bottom: number;
  /** The left coordinate in pixels. */
  left: number;
  /** The right coordinate in pixels. */
  right: number;
  /** The top coordinate in pixels. */
  top: number;
}
